<?php
require __DIR__.'/../shared/notification_bootstrap.php';require_once __DIR__.'/../shared/ticket_viability.php';require_once __DIR__.'/../shared/priority_colors.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
$operator=(string)(!empty($_SESSION['MKA_Usuario'])?$_SESSION['MKA_Usuario']:($_SESSION['MM_Usuario']??''));if(!$operator||!permissao('perm_chamados')){http_response_code(403);exit(json_encode(array('error'=>'Sem permissão.')));}
if(empty($_SESSION['suite_viability_csrf']))$_SESSION['suite_viability_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['suite_viability_csrf'];session_write_close();$conn->set_charset('utf8mb4');
try{if($_SERVER['REQUEST_METHOD']==='GET'){$technicians=$conn->query('SELECT id,nome FROM sis_func ORDER BY nome')->fetch_all(MYSQLI_ASSOC);echo json_encode(array('csrf'=>$csrf,'technicians'=>$technicians,'priorities'=>array_keys(mka_priority_colors($conn)),'today'=>(new DateTimeImmutable('now',new DateTimeZone('America/Sao_Paulo')))->format('Y-m-d')));}elseif($_SERVER['REQUEST_METHOD']==='POST'){$data=json_decode(file_get_contents('php://input',false,null,0,16000),true);if(!is_array($data)||!is_string($data['csrf']??null)||!hash_equals($csrf,$data['csrf'])){http_response_code(403);exit(json_encode(array('error'=>'Sessão expirada.')));}if(($data['action']??'')==='close'){mka_viability_schema($conn);$id=(int)($data['id']??0);$q=$conn->prepare("UPDATE sis_suporte s INNER JOIN suite_ticket_viability v ON v.ticket_id=s.id SET s.status='fechado',s.fechamento=NOW() WHERE s.id=? AND v.operator=? AND s.status='aberto'");$q->bind_param('is',$id,$operator);$q->execute();if($q->affected_rows!==1){http_response_code(403);exit(json_encode(array('error'=>'Chamado indisponível.')));}}else $id=mka_viability_save($conn,$operator,$data);echo json_encode(array('id'=>$id));}else{http_response_code(405);}}catch(InvalidArgumentException $e){http_response_code(422);echo json_encode(array('error'=>$e->getMessage()));}catch(Throwable $e){http_response_code(503);echo json_encode(array('error'=>'Não foi possível salvar. Tente novamente.'));}
